#include "mascot/MascotRenderer.h"

#include <algorithm>
#include <cstring>

#include "mascot_ps.h"   // generated by fxc at build time
#include "mascot_vs.h"

namespace eflow {

bool MascotRenderer::Init(ID3D11Device* device, const MascotAsset& asset) {
    meshes_.clear();
    textures_.clear();

    if (FAILED(device->CreateVertexShader(g_mascotVS, sizeof(g_mascotVS), nullptr, &vs_)) ||
        FAILED(device->CreatePixelShader(g_mascotPS, sizeof(g_mascotPS), nullptr, &ps_)))
        return false;
    const D3D11_INPUT_ELEMENT_DESC layout[] = {
        {"POSITION", 0, DXGI_FORMAT_R32G32B32_FLOAT, 0, offsetof(MascotAsset::Vertex, pos), D3D11_INPUT_PER_VERTEX_DATA, 0},
        {"TEXCOORD", 0, DXGI_FORMAT_R32G32_FLOAT, 0, offsetof(MascotAsset::Vertex, uv), D3D11_INPUT_PER_VERTEX_DATA, 0},
        {"BLENDINDICES", 0, DXGI_FORMAT_R8G8B8A8_UINT, 0, offsetof(MascotAsset::Vertex, joints), D3D11_INPUT_PER_VERTEX_DATA, 0},
        {"BLENDWEIGHT", 0, DXGI_FORMAT_R32G32B32A32_FLOAT, 0, offsetof(MascotAsset::Vertex, weights), D3D11_INPUT_PER_VERTEX_DATA, 0},
    };
    if (FAILED(device->CreateInputLayout(layout, ARRAYSIZE(layout), g_mascotVS, sizeof(g_mascotVS), &layout_)))
        return false;

    D3D11_BUFFER_DESC cb{sizeof(FrameConstants), D3D11_USAGE_DYNAMIC, D3D11_BIND_CONSTANT_BUFFER, D3D11_CPU_ACCESS_WRITE};
    if (FAILED(device->CreateBuffer(&cb, nullptr, &constants_))) return false;

    // Premultiplied "over".
    D3D11_BLEND_DESC bd{};
    auto& rt = bd.RenderTarget[0];
    rt.BlendEnable = TRUE;
    rt.SrcBlend = rt.SrcBlendAlpha = D3D11_BLEND_ONE;
    rt.DestBlend = rt.DestBlendAlpha = D3D11_BLEND_INV_SRC_ALPHA;
    rt.BlendOp = rt.BlendOpAlpha = D3D11_BLEND_OP_ADD;
    rt.RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
    if (FAILED(device->CreateBlendState(&bd, &blend_))) return false;

    D3D11_SAMPLER_DESC sd{};
    sd.Filter = D3D11_FILTER_MIN_MAG_MIP_LINEAR;    // mip-mapped: the art is drawn far smaller than authored
    sd.AddressU = sd.AddressV = sd.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
    sd.MaxLOD = D3D11_FLOAT32_MAX;
    if (FAILED(device->CreateSamplerState(&sd, &sampler_))) return false;

    D3D11_RASTERIZER_DESC rd{};
    rd.FillMode = D3D11_FILL_SOLID;
    rd.CullMode = D3D11_CULL_NONE;
    rd.DepthClipEnable = TRUE;
    if (FAILED(device->CreateRasterizerState(&rd, &raster_))) return false;

    Com<ID3D11DeviceContext> ctx;
    device->GetImmediateContext(&ctx);
    for (const auto& tex : asset.textures) {
        D3D11_TEXTURE2D_DESC td{};
        td.Width = tex.width;
        td.Height = tex.height;
        td.MipLevels = 0;                           // full chain, generated below
        td.ArraySize = 1;
        td.Format = DXGI_FORMAT_B8G8R8A8_UNORM;
        td.SampleDesc.Count = 1;
        td.BindFlags = D3D11_BIND_SHADER_RESOURCE | D3D11_BIND_RENDER_TARGET;
        td.MiscFlags = D3D11_RESOURCE_MISC_GENERATE_MIPS;
        Com<ID3D11Texture2D> t;
        Com<ID3D11ShaderResourceView> srv;
        if (FAILED(device->CreateTexture2D(&td, nullptr, &t)) || FAILED(device->CreateShaderResourceView(t.Get(), nullptr, &srv)))
            return false;
        ctx->UpdateSubresource(t.Get(), 0, nullptr, tex.bgra.data(), tex.width * 4, 0);
        ctx->GenerateMips(srv.Get());
        textures_.push_back(srv);
    }

    for (const auto& m : asset.meshes) {
        GpuMesh g;
        g.name = m.name;
        g.texture = m.texture;
        g.indexCount = static_cast<UINT>(m.indices.size());
        D3D11_BUFFER_DESC vbd{static_cast<UINT>(m.vertices.size() * sizeof(MascotAsset::Vertex)), D3D11_USAGE_IMMUTABLE,
                              D3D11_BIND_VERTEX_BUFFER};
        D3D11_SUBRESOURCE_DATA vdata{m.vertices.data()};
        D3D11_BUFFER_DESC ibd{static_cast<UINT>(m.indices.size() * sizeof(uint16_t)), D3D11_USAGE_IMMUTABLE,
                              D3D11_BIND_INDEX_BUFFER};
        D3D11_SUBRESOURCE_DATA idata{m.indices.data()};
        if (FAILED(device->CreateBuffer(&vbd, &vdata, &g.vb)) || FAILED(device->CreateBuffer(&ibd, &idata, &g.ib)))
            return false;
        meshes_.push_back(std::move(g));
    }
    // The base mesh is drawn first; face patches sit on top of it.
    std::stable_partition(meshes_.begin(), meshes_.end(), [](const GpuMesh& g) { return g.name == "eflow_base"; });
    return true;
}

void MascotRenderer::Draw(ID3D11DeviceContext* ctx, ID3D11RenderTargetView* target, UINT width, UINT height,
                          const DirectX::XMFLOAT4X4& viewProj, const std::vector<DirectX::XMFLOAT4X4>& skin,
                          const char* face, float opacity) {
    if (!vs_ || meshes_.empty()) return;

    D3D11_MAPPED_SUBRESOURCE mapped;
    if (FAILED(ctx->Map(constants_.Get(), 0, D3D11_MAP_WRITE_DISCARD, 0, &mapped))) return;
    auto* fc = static_cast<FrameConstants*>(mapped.pData);
    fc->viewProj = viewProj;
    const size_t n = std::min<size_t>(skin.size(), kMaxBones);
    std::copy_n(skin.begin(), n, fc->bones);
    fc->opacity = opacity;
    ctx->Unmap(constants_.Get(), 0);

    const D3D11_VIEWPORT vp{0, 0, static_cast<float>(width), static_cast<float>(height), 0, 1};
    ctx->OMSetRenderTargets(1, &target, nullptr);
    ctx->OMSetBlendState(blend_.Get(), nullptr, 0xffffffff);
    ctx->RSSetViewports(1, &vp);
    ctx->RSSetState(raster_.Get());
    ctx->IASetInputLayout(layout_.Get());
    ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
    ctx->VSSetShader(vs_.Get(), nullptr, 0);
    ctx->VSSetConstantBuffers(0, 1, constants_.GetAddressOf());
    ctx->PSSetShader(ps_.Get(), nullptr, 0);
    ctx->PSSetConstantBuffers(0, 1, constants_.GetAddressOf());
    ctx->PSSetSamplers(0, 1, sampler_.GetAddressOf());

    const std::string facePrefix = std::string("face_") + face + "_";
    for (const auto& m : meshes_) {
        if (m.name != "eflow_base" && m.name.rfind(facePrefix, 0) != 0) continue;
        if (m.texture < 0 || m.texture >= static_cast<int>(textures_.size())) continue;
        const UINT stride = sizeof(MascotAsset::Vertex), offset = 0;
        ctx->IASetVertexBuffers(0, 1, m.vb.GetAddressOf(), &stride, &offset);
        ctx->IASetIndexBuffer(m.ib.Get(), DXGI_FORMAT_R16_UINT, 0);
        ctx->PSSetShaderResources(0, 1, textures_[m.texture].GetAddressOf());
        ctx->DrawIndexed(m.indexCount, 0, 0);
    }
    ID3D11RenderTargetView* none = nullptr;
    ctx->OMSetRenderTargets(1, &none, nullptr);   // hand the back buffer back to Direct2D cleanly
}

} // namespace eflow
